import { createKvServer } from './server.ts';

const portArg = process.argv[2];
const port = Number(portArg);
if (portArg === undefined || !Number.isInteger(port) || port < 1 || port > 65535) {
  console.error('usage: app <port>');
  process.exit(2);
}

const server = createKvServer();
server.maxConnections = 1024;
server.on('error', (err) => {
  console.error(`server error: ${err.message}`);
  process.exit(1);
});
server.listen({ host: '127.0.0.1', port, backlog: 511 });

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => server.close(() => process.exit(0)));
}

import { createServer, type IncomingMessage, type Server, type ServerResponse } from 'node:http';
import { KvStore } from './store.ts';

export const MAX_VALUE_BYTES = 1024 * 1024;
const KEY_PATTERN = /^[A-Za-z0-9_-]{1,64}$/;
const KV_PREFIX = '/kv/';

class HttpError extends Error {
  readonly status: number;
  constructor(status: number) {
    super(`HTTP ${status}`);
    this.status = status;
  }
}

function send(
  res: ServerResponse,
  status: number,
  body: Buffer | string = '',
  contentType?: string,
): void {
  const payload = typeof body === 'string' ? Buffer.from(body) : body;
  if (contentType !== undefined) res.setHeader('Content-Type', contentType);
  if (status !== 204) res.setHeader('Content-Length', payload.length);
  res.writeHead(status);
  res.end(status === 204 ? undefined : payload);
}

async function readBody(req: IncomingMessage): Promise<Buffer> {
  const declared = Number(req.headers['content-length'] ?? 0);
  if (declared > MAX_VALUE_BYTES) throw new HttpError(413);
  const chunks: Buffer[] = [];
  let size = 0;
  for await (const chunk of req as AsyncIterable<Buffer>) {
    size += chunk.length;
    if (size > MAX_VALUE_BYTES) throw new HttpError(413);
    chunks.push(chunk);
  }
  return Buffer.concat(chunks, size);
}

type Handler = (req: IncomingMessage, res: ServerResponse) => Promise<void>;

export function createKvServer(store: KvStore = new KvStore()): Server {
  const handleKey = async (req: IncomingMessage, res: ServerResponse, key: string): Promise<void> => {
    switch (req.method) {
      case 'GET': {
        const value = store.get(key);
        if (value === undefined) send(res, 404);
        else send(res, 200, value, 'application/octet-stream');
        return;
      }
      case 'PUT': {
        const body = await readBody(req);
        send(res, store.put(key, body) ? 201 : 200);
        return;
      }
      case 'DELETE':
        send(res, store.delete(key) ? 204 : 404);
        return;
      default:
        send(res, 405);
    }
  };

  const route: Handler = async (req, res) => {
    const path = req.url ?? '/';
    if (path === '/health') {
      if (req.method === 'GET') send(res, 200, 'ok', 'text/plain');
      else send(res, 405);
      return;
    }
    if (path === '/kv') {
      if (req.method === 'GET') send(res, 200, JSON.stringify(store.keys()), 'application/json');
      else send(res, 405);
      return;
    }
    if (path.startsWith(KV_PREFIX)) {
      const key = path.slice(KV_PREFIX.length);
      if (!KEY_PATTERN.test(key)) {
        send(res, 400);
        return;
      }
      await handleKey(req, res, key);
      return;
    }
    send(res, 404);
  };

  return createServer({ keepAlive: false }, (req, res) => {
    route(req, res).catch((err: unknown) => {
      const status = err instanceof HttpError ? err.status : 500;
      if (!res.headersSent) {
        res.setHeader('Connection', 'close');
        send(res, status);
      } else {
        res.destroy();
      }
    });
  });
}

/** In-memory key-value store holding raw byte values. */
export class KvStore {
  readonly #data = new Map<string, Buffer>();

  get(key: string): Buffer | undefined {
    return this.#data.get(key);
  }

  /** Stores the value; returns true if the key was newly created. */
  put(key: string, value: Buffer): boolean {
    const created = !this.#data.has(key);
    this.#data.set(key, value);
    return created;
  }

  delete(key: string): boolean {
    return this.#data.delete(key);
  }

  /** All keys, sorted ascending. */
  keys(): string[] {
    return [...this.#data.keys()].sort();
  }
}

import { after, before, describe, it } from 'node:test';
import assert from 'node:assert/strict';
import type { AddressInfo } from 'node:net';
import { createKvServer, MAX_VALUE_BYTES } from '../src/server.ts';

const server = createKvServer();
let base = '';

before(async () => {
  await new Promise<void>((resolve) => server.listen(0, '127.0.0.1', resolve));
  base = `http://127.0.0.1:${(server.address() as AddressInfo).port}`;
});
after(() => server.close());

const req = (method: string, path: string, body?: Uint8Array<ArrayBuffer>) =>
  fetch(base + path, { method, ...(body ? { body } : {}), headers: { connection: 'close' } });

describe('kv server', () => {
  it('serves health', async () => {
    const res = await req('GET', '/health');
    assert.equal(res.status, 200);
    assert.equal(await res.text(), 'ok');
    assert.equal((await req('POST', '/health')).status, 405);
  });

  it('round-trips binary values', async () => {
    const value = new Uint8Array([0, 255, 13, 10, 200]);
    assert.equal((await req('PUT', '/kv/bin', value)).status, 201);
    assert.equal((await req('PUT', '/kv/bin', value)).status, 200);
    const res = await req('GET', '/kv/bin');
    assert.deepEqual(new Uint8Array(await res.arrayBuffer()), value);
    assert.equal((await req('DELETE', '/kv/bin')).status, 204);
    assert.equal((await req('DELETE', '/kv/bin')).status, 404);
  });

  it('lists keys sorted', async () => {
    for (const k of ['b', 'A', 'a']) await req('PUT', `/kv/${k}`, new Uint8Array([1]));
    const res = await req('GET', '/kv');
    assert.match(res.headers.get('content-type') ?? '', /application\/json/);
    assert.deepEqual(await res.json(), ['A', 'a', 'b']);
  });

  it('validates keys and routes', async () => {
    for (const p of ['/kv/', '/kv/a/b', '/kv/a.b', `/kv/${'x'.repeat(65)}`]) {
      assert.equal((await req('GET', p)).status, 400, p);
    }
    assert.equal((await req('GET', `/kv/${'x'.repeat(64)}`)).status, 404);
    assert.equal((await req('GET', '/other')).status, 404);
    assert.equal((await req('PATCH', '/kv/a')).status, 405);
    assert.equal((await req('POST', '/kv')).status, 405);
  });

  it('accepts a 1 MiB value and rejects larger', async () => {
    assert.equal((await req('PUT', '/kv/big', new Uint8Array(MAX_VALUE_BYTES))).status, 201);
    assert.equal((await req('PUT', '/kv/big2', new Uint8Array(MAX_VALUE_BYTES + 1))).status, 413);
  });
});
